import java.util.*;

public class Solution {
    public List<List<String>> findDuplicate(String[] paths) {
        // Map to store content -> list of full file paths
        Map<String, List<String>> contentMap = new HashMap<>();

        for (String path : paths) {
            // Split by space to separate directory and files
            String[] parts = path.split(" ");
            String directory = parts[0];

            for (int i = 1; i < parts.length; i++) {
                String fileInfo = parts[i];

                // Find indices of parentheses to extract content
                int openParenthesis = fileInfo.indexOf('(');
                int closeParenthesis = fileInfo.indexOf(')');

                String fileName = fileInfo.substring(0, openParenthesis);
                String content = fileInfo.substring(openParenthesis + 1, closeParenthesis);

                // Construct the full absolute file path
                String fullPath = directory + "/" + fileName;

                // Add to the map
                contentMap.putIfAbsent(content, new ArrayList<>());
                contentMap.get(content).add(fullPath);
            }
        }

        // Collect all groups that have a size greater than 1 (meaning they are duplicates)
        List<List<String>> result = new ArrayList<>();
        for (List<String> filePaths : contentMap.values()) {
            if (filePaths.size() > 1) {
                result.add(filePaths);
            }
        }

        return result;
    }
}
